{
  "name": "Butterfly chart (horizontal)",
  "category": "organism",
  "purpose": "Two-series comparison per category as mirrored horizontal bars flowing outward from a shared centre gutter — e.g. this-year versus last-year, actual versus target, inflow versus outflow. Semantic SVG in the DOM, styled by tokens, animated by CSS, behaviour by the ONE generated dv-behaviour partial (ADR-0015, worker fence — markers empty). CHART-EXPANSION WAVE 2 lane 1 (2026-08-05); ported from Chart-bar.reference.html's mark contract and Chart-line.reference.html's Layer-2 state model.",
  "props": [
    { "name": "series", "type": "pair", "$note": "Exactly two series, one per direction. LEFT takes data/series/1 (categorical default); RIGHT takes data/series/3 (DV-D09's h-bar default, cited here for the positive-reading direction)." },
    { "name": "data", "type": "table", "$note": "A real <table class=\"dv-table\"> inside the figure — the a11y spine AND the tabular alternative (dv-005), surfaced by the same TABLE-VIEW POPOVER Chart-bar uses." },
    { "name": "empty", "type": "boolean", "default": false, "$note": "No-data state consumes the Empty-state pattern by reference." }
  ],
  "variants": [
    { "name": "mirrored horizontal, two series", "use": "Compare two measures per category, both readable at a glance without stacking or grouping side-by-side." }
  ],
