{
  "name": "Accordion",
  "category": "molecule",
  "purpose": "A disclosure control that collapses/expands a section of content behind a titled header. Used to reduce clutter and cognitive load on content-heavy pages or where a range of user needs must be covered (e.g. FAQs). For a single disclosure on its own, prefer an Expand link rather than a lone accordion.",
  "props": [
    { "name": "variant", "type": "enum", "values": ["standard", "inline"], "default": "standard" },
    { "name": "open", "type": "boolean", "values": ["false", "true"], "default": "false" },
    { "name": "state", "type": "enum", "values": ["default", "hover", "pressed"], "default": "default" },
    { "name": "fontSize", "type": "enum", "values": ["4", "5", "6"], "default": "4" },
    { "name": "size", "type": "enum", "values": ["5", "6"], "default": "5" }
  ],
  "variants": [
    { "name": "standard", "use": "Default accordion on white surfaces; titled section disclosure. Title uses the font-4 scale (covers display scales 1-3) or font-5." },
    { "name": "inline", "use": "Compact, link-style disclosure for dense layouts or within running content; smaller footprint (size 5/6)." }
  ],
  "tokens": {
    "rule-top": "border/subtle",
    "title-text": "text/default",
    "icon": "icon/default",
    "background": "background/default",
    "background-hover": "tertiary/background/hover",
    "background-pressed": "tertiary/background/pressed",
    "header-padding-top": "padding/responsive/xxxsmall",
    "title-type-standard": "font-4/regular",
    "title-type-inline": "font-5/medium"
  },
  "relationships": {
    "livesInside": ["Page", "Form", "Card", "Tab panel"],
    "mustNotNeighbour": [],
    "commonPatterns": ["FAQ list", "grouped form sections", "progressive disclosure of secondary content", "stacked into an accordion group"]
  },
  "accessibility": {
    "role": "Header is a button that controls a collapsible region (disclosure pattern)",
    "keyboard": "Header is reachable in tab order; Enter and Space toggle open/closed",
    "focus": "REVIEW: the Figma component set defines default/hover/pressed but no explicit focus-visible state — confirm a visible focus indicator exists in code",
    "screenReader": "Header button exposes aria-expanded reflecting open state; arrow icon is decorative (aria-hidden); content region associated to the header (aria-controls / region labelled by the title)",
    "relatedSC": ["2.1.1 Keyboard", "2.4.7 Focus Visible", "4.1.2 Name, Role, Value", "1.4.3 Contrast (Minimum)", "2.5.8 Target Size (Minimum)"]
  },
  "antiPatterns": [
    "Using a single accordion on its own — use an Expand link instead (per HSBC guidance)",
    "Changing an accordion title after the user completes its action (e.g. relabelling to 'Personal details entered') — titles must stay stable (per HSBC guidance)",
    "Title case or inconsistent casing — titles are written in sentence case (per HSBC guidance)",
    "Vague or overlong titles — keep concise, descriptive, and consistent in grammar and tone (per HSBC guidance)",
    "REVIEW (inferred): hiding required or critical information inside a collapsed panel",
    "REVIEW (inferred): deeply nesting accordions within accordions",
    "REVIEW (inferred): hard-coding the header text colour or rule colour instead of binding text/default and border/subtle tokens"
  ],
  "tokenValidation": {
    "date": "2026-06-17",
    "against": "token store re-based on Figma native variable export (semantic-colour.json, spacing.json, typography.json)",
    "result": "PASS — all 9 token refs resolve; none deprecated",
    "notes": "Colour tokens resolve in both light and dark modes. background-pressed = tertiary/background/pressed (light #767676) is intentionally strong: per Dave, WCAG state differentiation needs more than a single colour change, and active/pressed warrants more contrast than hover — the pressed state combines two colour changes plus an icon change, which clears that bar. Acknowledged as possibly heavy-handed; may be revisited but not a defect. dark-mode semantics are partly in the in-progress Sutherland remap; re-check if those modes change."
  },
  "provenance": {
    "source": "figma",
    "figma_node": "mI8hvIkV98nquoqWzKh5Kn:433:13167",
    "code_path": ""
  },
