{
  "name": "Account card",
  "interactive": false,
  "category": "molecule",
  "purpose": "A passive summary card for a single account: the account label (name · masked number), its balance in the display/amount type, and an optional meta row showing account type (Tags atom) and a RAG status (Status-indicator chip). Surfaced as a missing pattern by the payments-journey gap report.",
  "props": [
    { "name": "status", "type": "enum", "values": ["none", "ok", "warn", "err", "info"], "default": "none", "$note": "Optional RAG status chip in the meta row; meaning carried by the label text, not the dot." },
    { "name": "tag", "type": "boolean", "default": false, "$note": "Optional account-type tag (Tags atom)." }
  ],
  "variants": [
    { "name": "default", "use": "Label + balance + meta row (type tag + status chip)." },
    { "name": "minimal", "use": "Label + balance only (no meta row)." }
  ],
  "tokens": {
    "surface": "tertiary/background/default",
