    "muted": "text/secondary",
    "tag-border": "form/border/default",
    "status-ok": "rag/success",
    "status-ok-tint": "rag/success-tint",
    "status-warn": "rag/warning",
    "status-warn-tint": "rag/warning-tint",
    "font-family": "typography/font-family/default",
    "$balance-type-finding": "REVIEW: the balance uses a display/amount type (30px / line-height 1.1 / tabular-nums / -0.01em) with NO dedicated typography token. The gap report flagged 'display/amount type + money-format' as missing — confirm the size/role and add a token, or bind to an existing display type."
  },
  "relationships": {
    "livesInside": ["Dashboard / accounts screen", "Account list"],
